        ||($budget['planned_record_count']??null)!==16||($budget['profile_sha256']??null)!==HOTEL_PROFILE_SHA
        ||HotelServerInputs::json($budget['profile']??null)!==HotelServerInputs::json($profile)
        ||($budget['accounting']??null)!=='full_reserved_ceiling_not_provider_invoice'||($budget['maximum_calls']??null)!==8
        ||($budget['output_tokens_cap']??null)!==2200||($budget['input_usage_guard']??null)!==$policy['input_token_ceiling']
        ||($budget['tokens_per_call_reservation']??null)!==$plan['limits']['tokens_per_call']
        ||($budget['reserved_micros_per_call']??null)!==$plan['limits']['micros_per_call']
        ||($budget['maximum_reserved_micros']??null)!==$plan['limits']['max_micros']
        ||($budget['valid_until']??null)!==$policy['valid_until']||$policy['budget_attestation_sha256']!==HOTEL_BUDGET_SHA
        ||!is_string($budget['owner_decision']??null)||trim($budget['owner_decision'])==='')hotelFail('new_budget_attestation_unconfirmed');
    $l=$plan['limits'];
    if($l['deadline']!==HOTEL_LAUNCH_DEADLINE||$l['deadline']!==$policy['valid_until']||$l['deadline']<=time()+900||$l['deadline']>time()+86400||$l['max_calls']!==8
        ||$l['max_tokens']!==8*$l['tokens_per_call']||$l['max_micros']!==8*$l['micros_per_call']
        ||$l['tokens_per_call']!==1052200||$l['micros_per_call']!==11000000
        ||$policy['input_token_ceiling']!==1000000||$policy['reserved_micros_minimum']!==11000000||$policy['max_source_age_seconds']!==86400)hotelFail('new_budget_or_deadline_unconfirmed');
    if(!is_array($plan['stages'])||!array_is_list($plan['stages'])||count($plan['stages'])!==4)hotelFail('four_country_plan_required');
    $seen=[];foreach(['EG','TH','VN','TR'] as $stage=>$country){
        $scopes=$plan['stages'][$stage];if(!is_array($scopes)||!array_is_list($scopes)||count($scopes)!==4)hotelFail('sixteen_scope_plan_required');
        foreach($scopes as $scope){$key=HotelServerInputs::key($scope);if(($scope['country']??null)!==$country||isset($seen[$key]))hotelFail('planned_scope_identity_unconfirmed');$seen[$key]=true;}
    }
}

// BEGIN PURE TERMINAL BOUNDARY
/** Pure gate shared verbatim with the pre-credential fixture. No database or provider access. */
function hotelCheckTerminalBoundary(array $row,array $expected,bool $enabled,?string $resolvedBaseline): array {
    foreach(['campaign_id','bootstrap_sha256','inputs_sha256'] as $field)
        if(!is_string($expected[$field]??null)||($row[$field]??null)!==$expected[$field])hotelFail('predecessor_CAS');
    if(($row['state']??null)!=='complete'||!is_string($row['baseline_sha256']??null)
        ||!preg_match('/\A[a-f0-9]{64}\z/D',$row['baseline_sha256'])
        ||($resolvedBaseline!==null&&!hash_equals($resolvedBaseline,$row['baseline_sha256'])))hotelFail('predecessor_CAS');
    $counts=['enabled'=>$enabled?1:0,'stage_cursor'=>4,'new_accepted'=>4,'historical_accepted'=>19,
        'reserved_calls'=>8,'reserved_tokens'=>8417600,'reserved_micros'=>88000000];
    foreach($counts as $field=>$value){
        $actual=$row[$field]??null;
        if(!(is_int($actual)||(is_string($actual)&&preg_match('/\A(?:0|[1-9][0-9]*)\z/D',$actual)))
            ||(string)$actual!==(string)$value)hotelFail('predecessor_CAS');
        $row[$field]=$value;
    }
    return $row;
}
